function uuid(){const a=crypto.getRandomValues(new Uint8Array(16));a[6]=(a[6]&15)|64;a[8]=(a[8]&63)|128;const h=[...a].map(x=>x.toString(16).padStart(2,'0')).join('');return [h.slice(0,8),h.slice(8,12),h.slice(12,16),h.slice(16,20),h.slice(20)].join('-')}

const initial={page:{title:'상상에서 시작해,\n나만의 작품으로.',description:'어피니티 유니버스에서 나에게 맞는 창작 과정을 만나보세요.',courses:[{name:'아트북',description:'상상을 그림과 이야기로 표현하는 창작 과정'},{name:'픽처북',description:'나의 이야기를 한 권의 그림책으로 완성하는 과정'},{name:'드로잉북',description:'나만의 시선과 표현을 발견하는 드로잉 과정'}]},published:null,leads:[],rules:[{id:'r1',keyword:'클래스,그림책,수강료',reply:'안녕하세요! 어피니티 유니버스입니다. 관심 있는 창작 과정과 상담 신청은 소개 페이지에서 확인해 주세요.',enabled:true}],posts:[],events:[]};
let data=structuredClone(initial),revision=-1,isAdmin=false,totalVisits=0,syncData=[],linkData={links:[],marketers:[],history:[]};
const customerView=()=>location.pathname==='/consult'||new URLSearchParams(location.search).has('ref')||location.hash==='#visitor';
async function api(path,method='GET',body){const res=await fetch('/api/'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const result=await res.json();if(!res.ok){const e=Error(result.error||'요청에 실패했습니다.');e.details=result;throw e;}return result}
let saveQueue=Promise.resolve();
function save(){const config=structuredClone({page:data.page,published:data.published,rules:data.rules});const job=saveQueue.then(async()=>{const result=await api('admin/state','PUT',{config,revision});revision=result.revision;});saveQueue=job.catch(()=>{});return job}
const embedded=location.pathname==='/admin/console'&&new URLSearchParams(location.search).get('embed')==='1';let current=location.pathname==='/admin/console'?(['links','funnel'].includes(new URLSearchParams(location.search).get('view'))?new URLSearchParams(location.search).get('view'):'leads'):location.pathname==='/admin/links'?'links':'overview';const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
