function shell(){if(customerView()){visitor();return}if(!isAdmin){$('#app').innerHTML='<main class=visitor><h1>관리자 권한이 필요합니다.</h1><a href="/consult">클래스 상담 페이지로 이동</a></main>';return}if(embedded){$('#app').innerHTML='<main class="console-main"><div id="content"></div></main>';render();return}$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="logo-badge"><img src="https://affinity-universe-studio.veldy-1025.chatgpt.site/assets/affinity-seal-silver.png" alt="어피니티 유니버스 로고" width="52" height="52"></span><div>AFFINITY<br>UNIVERSE<small>STUDIO</small></div></div><div class="workspace"><strong>어피니티 유니버스</strong>브랜드 운영 워크스페이스</div><nav class="nav">${Object.keys(names).map(k=>`<button data-nav="${k}" class="${current===k?'active':''}">${icon(k)}${names[k]}</button>`).join('')}</nav></aside><main class="main"><header class="topbar"><div class="crumb">워크스페이스 &nbsp; / &nbsp; ${names[current]}</div><div class="actions"><button class="light" id="previewBtn">방문자 화면 ↗</button></div></header><div id="content"></div></main></div>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=async()=>{try{if(['overview','leads','links'].includes(b.dataset.nav)){await saveQueue;await refreshState();if(b.dataset.nav==='links')await refreshLinks()}current=b.dataset.nav;shell()}catch(e){toast(e.message)}});$('#previewBtn').onclick=()=>{location.hash='visitor'};render()}
