function studentMetricsView(){return `<section class="panel"><div class="panelhead"><h2>학생 현황</h2><a class="light" href="https://affinity-growth-bi-veldy-1025.veldy-1025.chatgpt.site" target="_blank" rel="noopener">Growth BI에서 조회 ↗</a></div><p>먼데이 기준으로 집계하며, 조회 기간은 한 달입니다.</p><div class="row"><div>인포허브 전체 학생<small>인포허브에 연결된 전체 학생 · 학생 DB ID 기준 중복 제외 · 조회 월과 무관</small></div></div><div class="row"><div>월 기준 회차 도달 수강생<small>현재 수강 중이며 지정 회차에 도달한 학생 · 해당 회차 수업일이 조회 월에 속하고 오늘까지 지난 경우 · 학생 중복 제외</small></div></div><p class="hint">12강 과정 1·5·10강 / 아트북 2·5·8강 / 브랜딩 1·5·9·13·17강. 현재 진행 회차와 수업일을 기준으로 계산하며 실제 출석 수치는 아닙니다.</p><div class="row"><div>2026 유료 등록 기록<small>2026년 입금된 CLEAR·SPLIT 기록 · 같은 학생의 반복 등록과 분할 입금 기록 포함</small></div></div><p class="hint">개발 중인 Studio 상담 기록은 학생 집계에서 제외합니다. 실제 수치는 관리자 권한으로 Growth BI에서 확인할 수 있습니다.</p></section>`}
function overview(){let counts=['신규 문의','상담 중','등록 완료'].map(s=>data.leads.filter(l=>l.status===s).length);return heading('창작의 시작을, 더 가깝게.','소개부터 상담까지, 어피니티의 고객 여정을 한곳에서 관리하세요.',`<button class="primary" id="newLead">+ 상담 추가</button>`)+studentMetricsView()+`<div class="hero"><div><div class="eyebrow">YOUR BRAND, YOUR SYSTEM</div><h2>좋은 클래스를 발견하고,<br>첫 상담으로 이어지는 공간.</h2><p>우리만의 소개 페이지와 운영 도구를 직접 만들어 갑니다.</p><button data-go="page">소개 페이지 편집하기 &nbsp; ↗</button></div><div class="orbit"><div class="star">✳</div><span class="orbittag one">상상 → 작품</span><span class="orbittag two">관심 → 첫 만남</span></div></div><div class="stats">${[['페이지 방문',totalVisits,'세션별 서버 기록 · 링크별 집계'],['접수된 상담',data.leads.length,'직접 추가 및 테스트 접수 포함'],['상담 진행 중',counts[1],'진행 상태 기준'],['등록 완료',counts[2],'운영자가 변경한 상태 기준']].map(([a,b,c])=>`<div class="stat"><span class="label">${a}</span><strong>${b}<span style="font-size:13px"> ${a==='페이지 방문'?'회':'건'}</span></strong><small>${c}</small></div>`).join('')}</div><div class="grid2"><section class="panel"><div class="panelhead"><h2>관심이 등록으로 이어지는 흐름</h2><span class="pill">현재 누적</span></div><div class="flow">${counts.map((n,i)=>`<div class="flowstep"><small>${['01 · 신규 문의','02 · 상담 진행','03 · 등록 완료'][i]}</small><b>${n}</b></div>`).join('')}</div><p style="font-size:11px">실제 광고 성과가 아닌, 현재 저장된 상담 상태의 분포입니다.</p></section><section class="panel"><div class="panelhead"><h2>운영 준비</h2><button class="ghost" data-go="settings">전체 보기 ↗</button></div><div class="row"><div>소개 페이지<small>코스 안내와 상담 신청</small></div><span class="pill">${data.published?'발행본 있음':'초안 작성 중'}</span></div><div class="row"><div>자동 응답 규칙<small>키워드와 문구를 먼저 테스트</small></div><span class="pill">${data.rules.filter(r=>r.enabled).length}개 활성</span></div><div class="row"><div>SNS 연결<small>Instagram · Threads · YouTube</small></div><span class="pill gray">미연결</span></div></section><section class="panel"><div class="panelhead"><h2>최근 상담</h2><button class="ghost" data-go="leads">모두 보기 ↗</button></div>${data.leads.length?data.leads.slice(-3).reverse().map(l=>`<div class="row"><div>${esc(l.name)}<small>${esc(l.course)} · ${esc(l.source)}</small></div><span class="pill">${esc(l.status)}</span></div>`).join(''):`<div class="empty">아직 접수된 상담이 없습니다.<br>방문자 화면에서 첫 상담 흐름을 테스트해 보세요.</div>`}</section></div>`}
function mediaElement(m,compact=false){const url='/api/media/'+encodeURIComponent(m.id);return m.kind==='video'?`<video class="course-media ${compact?'compact':''}" controls preload="metadata" playsinline src="${url}" aria-label="${esc(m.name||'코스 동영상')}"></video>`:`<img class="course-media ${compact?'compact':''}" src="${url}" alt="${esc(m.name||'코스 이미지')}" loading="lazy">`}
function courseMedia(c){const files=c.media||[],cover=files.find(m=>m.id===c.coverId)||files[0];if(!cover)return '';return `<div class="course-media-gallery">${mediaElement(cover)}${files.length>1?`<div class="media-grid">${files.filter(m=>m.id!==cover.id).map(m=>mediaElement(m,true)).join('')}</div>`:''}</div>`}
function phone(p,full=false){return `<div class="phone"><div class="phonehead"><div class="phonebrand"><span class="logo-badge"><img src="https://affinity-universe-studio.veldy-1025.chatgpt.site/assets/affinity-seal-silver.png" alt="어피니티 유니버스 로고" width="40" height="40"></span><span>AFFINITY UNIVERSE</span></div><div class="art" aria-hidden="true"><span>✷</span><span>✿</span><span>✦</span></div><h2>${esc(p.title).replace(/\n/g,'<br>')}</h2><p>${esc(p.description)}</p></div><div class="phonebody"><div class="eyebrow">FIND YOUR CREATIVE COURSE</div>${p.courses.map((c,i)=>`<article class="public-course"><div class="course"><div><b>${esc(c.name)}</b><small>${esc(c.description)}</small></div>${full?`<button class="ghost" data-interest="${i}" aria-label="${esc(c.name)} 상담 신청">↗</button>`:'<span>↗</span>'}</div>${courseMedia(c)}</article>`).join('')||'<p class="empty">소개할 코스를 준비하고 있습니다.</p>'}<button class="primary" ${full?'id="requestConsult"':'disabled'}>나에게 맞는 클래스 상담하기 &nbsp; →</button><p class="hint">${full?'신청하신 내용은 담당자가 확인 후 안내드립니다.':'고객용 페이지에서 상담을 신청할 수 있습니다.'}</p></div></div>`}
function normalizeCourses(){data.page.courses.forEach(c=>{c.id=c.id||uuid();c.media=c.media||[]})}
function editor(){normalizeCourses();return heading('우리의 이야기를 담는 페이지','코스와 미디어를 구성하고 고객용 페이지에 발행하세요.',`<button class="primary" id="publishPage">발행본 저장</button>`)+`<div class="editor"><section class="panel"><h2>페이지 콘텐츠</h2><label for="pageTitle">메인 문구</label><textarea id="pageTitle" maxlength="120">${esc(data.page.title)}</textarea><label for="pageDesc">소개 문구</label><textarea id="pageDesc" maxlength="400">${esc(data.page.description)}</textarea><div class="panelhead" style="margin-top:24px"><h3>코스 안내 · ${data.page.courses.length}개</h3><button class="light" id="addCourse">+ 코스 추가</button></div><p class="hint">사진·GIF는 파일당 10MB, MP4·WebM 동영상은 25MB까지 첨부할 수 있습니다. 코스별 최대 12개입니다.</p>${data.page.courses.map((c,i)=>`<div class="courseedit" data-course-card="${esc(c.id)}"><div class="panelhead"><h3>코스 ${i+1}</h3><div class="actions"><button class="ghost" data-move-course="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="코스 ${i+1} 위로">↑</button><button class="ghost" data-move-course="${i}" data-direction="1" ${i===data.page.courses.length-1?'disabled':''} aria-label="코스 ${i+1} 아래로">↓</button><button class="ghost" data-remove-course="${i}">코스 삭제</button></div></div><label for="cn${i}">코스 이름</label><input id="cn${i}" maxlength="60" value="${esc(c.name)}" data-course-name="${i}"><label for="cd${i}">코스 설명</label><input id="cd${i}" maxlength="160" value="${esc(c.description)}" data-course-desc="${i}"><label for="media${i}">사진 · GIF · 동영상 첨부</label><input type="file" id="media${i}" data-course-upload="${esc(c.id)}" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm" multiple><div class="attachment-list">${c.media.map(m=>`<div class="attachment-card">${mediaElement(m,true)}<small>${esc(m.name)}</small><div class="actions"><button class="ghost" data-cover-course="${i}" data-media-id="${esc(m.id)}">${(c.coverId||c.media[0]?.id)===m.id?'✓ 대표 미디어':'대표로 선택'}</button><button class="ghost" data-remove-media="${i}" data-media-id="${esc(m.id)}">첨부 제거</button></div></div>`).join('')}</div></div>`).join('')||'<p class="empty">코스를 추가해 주세요.</p>'}<p id="editorSaveState" class="hint" role="status">초안은 자동 저장됩니다. 발행본 저장 후 고객 화면에 반영됩니다.</p></section><aside class="previewwrap"><div class="eyebrow">LIVE PREVIEW</div><div id="phonePreview">${phone(data.page)}</div></aside></div>`}
function formatLeadDate(l){const raw=l.submittedAt||l.createdAt;if(raw){try{const options={dateStyle:'medium',timeStyle:'short'};if(actualZone(l)!=='확인 불가')options.timeZone=actualZone(l);return new Intl.DateTimeFormat('ko-KR',options).format(new Date(raw))}catch{}}return l.date||'확인 불가'}
function leadLocation(l){const place=[l.locationCountry,l.locationRegion].filter(v=>v&&v!=='확인 불가').join(' · ');return place||'국가·지역 확인 불가'}
function leadTimezone(l){return l.locationTimezone&&l.locationTimezone!=='확인 불가'?l.locationTimezone:'시간대 확인 불가'}
const consultationStates=['신규 문의','상담 중','등록 완료','보류','취소'],paymentStates=['결제 대기','결제 확인','부분 결제','취소'];
function op(l){return {studentName:'',classSchedule:'',instructor:'',specialNotes:'',studentDBId:'',trialDate:'',enrollmentDate:'',renewalDate:'',country:'',region:'',city:'',timezone:'',availability:'',guardianName:'',device:'',preferredSchedule:'',paymentStatus:'결제 대기',paymentMethod:'',payerName:'',paymentEmail:'',amount:0,paidAmount:0,paymentDate:'',confirmedCurriculum:'',commissionRate:10,...l.operations}}
function actualCountry(l){return op(l).country||l.residence?.country||l.locationCountry||'확인 불가'}function actualRegion(l){return op(l).region||l.residence?.region||l.locationRegion||'확인 불가'}function actualZone(l){return op(l).timezone||l.residence?.timezone||l.locationTimezone||'확인 불가'}
function localClock(l){try{return new Intl.DateTimeFormat('ko-KR',{timeZone:actualZone(l),month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date())}catch{return '시간대 확인 필요'}}
function syncInfo(l){return syncData.find(s=>s.lead_id===l.id)||{state:'pending'}}
function syncLabel(l){const s=syncInfo(l);return s.summary||({pending:'동기화 대기',synced:'동기화 완료',running:'전송 중',review:'결과 확인 필요'}[s.state]||'동기화 대기')}
function syncBoards(l,detail=false){const s=syncInfo(l),d=s.destinations;if(!d)return `<span class="pill">${esc(syncLabel(l))}</span>`;return `<div class="sync-destinations"><div><strong>Distance</strong><span class="pill">${esc(d.distance.label)}</span></div><div><strong>Revenue</strong><span class="pill ${d.revenue.state==='synced'?'':'gray'}">${esc(d.revenue.label)}</span></div>${detail?`<p class="hint">${esc(d.revenue.reason)}</p><p class="hint">${d.distance.itemId?'Distance 아이템 ID: '+esc(d.distance.itemId):''}${d.revenue.itemId?'<br>Revenue 아이템 ID: '+esc(d.revenue.itemId):''}</p>`:''}</div>`}
function options(values,placeholder){return '<option value="">'+placeholder+'</option>'+[...new Set(values.filter(Boolean))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}
function leads(){return heading('상담부터 등록까지, 한 화면에서.','상담·결제 정보 관리 · 저장 후 전송 시 Monday 테스트 보드 반영',`<button class="primary" id="newLead">+ 상담 추가</button>`)+`<div class="toolbar"><input data-lead-filter id="leadSearch" aria-label="상담 검색" placeholder="이름 · 연락처 · 코스 · 문의 내용" style="max-width:290px"><select data-lead-filter id="statusFilter" aria-label="상담 상태">${options(consultationStates,'전체 상담 상태')}</select><select data-lead-filter id="paymentFilter" aria-label="결제 상태">${options(paymentStates,'전체 결제 상태')}</select><select data-lead-filter id="marketerFilter" aria-label="마케터"><option value="">전체 마케터</option>${[...new Map(data.leads.filter(l=>l.marketerId).map(l=>[l.marketerId,l.marketerName])).entries()].map(([id,name])=>`<option value="${esc(id)}">${esc(name)}</option>`).join('')}</select><select data-lead-filter id="channelFilter" aria-label="유입 채널">${options(data.leads.map(l=>l.referralChannel),'전체 채널')}</select><select data-lead-filter id="countryFilter" aria-label="국가">${options(data.leads.map(actualCountry),'전체 국가')}</select><select data-lead-filter id="regionFilter" aria-label="지역">${options(data.leads.map(actualRegion),'전체 지역')}</select><select data-lead-filter id="zoneFilter" aria-label="시간대">${options(data.leads.map(actualZone),'전체 시간대')}</select><select data-lead-filter id="courseFilter" aria-label="코스">${options(data.leads.map(l=>l.course),'전체 코스')}</select><select data-lead-filter id="archiveFilter" aria-label="보관 상태"><option value="active">운영 중</option><option value="archived">보관함</option><option value="all">전체 포함</option></select><label class="date-filter">접수일(한국 기준)<input data-lead-filter id="dateFromFilter" type="date" aria-label="접수 시작일"></label><label class="date-filter">부터<input data-lead-filter id="dateToFilter" type="date" aria-label="접수 종료일"></label><button class="light" id="reloadLeads">새로고침</button><button class="light" id="exportLeads">전체 CSV</button><button class="light" id="showLeadTrash">삭제함 (${deletedLeads.length})</button></div><section class="panel"><div class="tablewrap"><table><thead><tr><th>이름 / 연락처</th><th>코스 / 유입</th><th>접수 / 고객 현지 시각</th><th>상담 상태</th><th>결제 / 입금액</th><th>Monday / 상세</th></tr></thead><tbody id="leadRows">${leadRows()}</tbody></table></div></section><p class="hint">고객이 직접 선택한 거주 지역·시간대가 기본으로 표시되며 상담 상세에서 확인·수정할 수 있습니다. 접속 위치 자동 감지 정보는 원본으로 유지됩니다. 보관해도 과거 마케터 실적과 변경 이력은 유지됩니다.</p>`}
function filteredLeads(){const val=id=>$('#'+id)?.value||'',q=val('leadSearch').toLowerCase(),archive=val('archiveFilter')||'active';return data.leads.filter(l=>(archive==='all'||(archive==='archived'?l.archived:!l.archived))&&(!val('statusFilter')||l.status===val('statusFilter'))&&(!val('paymentFilter')||op(l).paymentStatus===val('paymentFilter'))&&(!val('marketerFilter')||l.marketerId===val('marketerFilter'))&&(!val('channelFilter')||l.referralChannel===val('channelFilter'))&&(!val('countryFilter')||actualCountry(l)===val('countryFilter'))&&(!val('regionFilter')||actualRegion(l)===val('regionFilter'))&&(!val('zoneFilter')||actualZone(l)===val('zoneFilter'))&&(!val('courseFilter')||l.course===val('courseFilter'))&&(!val('dateFromFilter')||l.date>=val('dateFromFilter'))&&(!val('dateToFilter')||l.date<=val('dateToFilter'))&&[l.name,l.contact,l.course,l.message,l.note,l.marketerName,l.referralCode,actualCountry(l),actualRegion(l)].join(' ').toLowerCase().includes(q))}
function leadRows(){return orderedLeads().map(l=>`<tr data-lead-row="${esc(l.id)}"><td><button class="ghost lead-drag" draggable="true" data-drag-lead="${esc(l.id)}" aria-label="${esc(l.name)} 순서 이동" title="끌어서 순서 변경 · 방향키 위아래로 이동">⠿</button><strong>${esc(l.name)}</strong><p class="hint">${esc(l.contact)}${l.archived?' · 보관됨':''}</p></td><td>${esc(l.course)}<p class="hint">${esc(l.marketerName||'미배정')} · ${esc(l.referralChannel||l.source)}${l.sourceDetail?' · '+esc(l.sourceDetail):''}</p></td><td>${esc(formatLeadDate(l))}<p class="hint">${esc(actualCountry(l))} · ${esc(actualRegion(l))}<br><span data-local-clock="${esc(l.id)}">${esc(localClock(l))}</span> · ${esc(actualZone(l))}<br>연락 가능: ${esc(op(l).availability||'미입력')}</p></td><td><select data-status="${esc(l.id)}" aria-label="${esc(l.name)} 상담 상태" ${syncInfo(l).state==='running'?'disabled':''}>${consultationStates.map(s=>`<option ${l.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td>${esc(op(l).paymentStatus)}<p class="hint">${Number(op(l).paidAmount).toLocaleString('ko-KR')} / ${Number(op(l).amount).toLocaleString('ko-KR')}원</p></td><td>${syncBoards(l)}<button class="ghost" data-detail="${esc(l.id)}">상담 · 결제 관리 ↗</button><button class="ghost" data-delete-lead="${esc(l.id)}">삭제</button></td></tr>`).join('')||'<tr><td colspan="6" style="text-align:center">조건에 맞는 상담이 없습니다.</td></tr>'}
function rules(){return heading('반복되는 질문에, 일관된 답변.','키워드 규칙을 만들고 발송 전 응답을 테스트하세요.',`<button class="primary" id="newRule">+ 규칙 추가</button>`)+`<div class="banner">SNS 미연결 · 현재는 응답 규칙 저장과 시뮬레이션을 지원합니다. 외부 댓글이나 DM에 실제로 발송하지 않습니다.</div><div class="rulegrid"><section class="panel"><h2>응답 규칙</h2>${data.rules.map(r=>`<div class="row"><div style="flex:1"><h3>${esc(r.keyword.split(',').join(' · '))}</h3><p style="font-size:12px;white-space:pre-wrap">${esc(r.reply)}</p><button class="ghost" data-edit-rule="${r.id}">편집</button></div><button class="light" data-toggle-rule="${r.id}" aria-pressed="${r.enabled}">${r.enabled?'활성':'일시 중지'}</button></div>`).join('')||'<div class="empty">규칙을 추가해 주세요.</div>'}</section><section class="panel"><div class="eyebrow">REPLY PLAYGROUND</div><h2>실제로 어떻게 답할까요?</h2><label for="testMessage">받은 메시지 예시</label><textarea id="testMessage" placeholder="예: 그림책 클래스에 대해 알고 싶어요."></textarea><button class="primary" id="testReply" style="margin-top:16px">응답 테스트</button><div id="replyResult" aria-live="polite"><div class="empty" style="margin-top:20px">메시지를 입력하면 적용되는 규칙과<br>응답 문구를 확인할 수 있습니다.</div></div><p class="hint">쉼표로 구분한 키워드 중 하나를 포함하면 일치합니다. 여러 규칙이 맞으면 목록의 첫 활성 규칙을 적용합니다.</p></section></div>`}
function settings(){return heading('연동 · 데이터','문의와 마케터 유입 정보는 서버에 저장됩니다.')+`<div class="grid2"><section class="panel"><h2>저장 및 접근</h2><p>고객용 페이지와 관리자 기능이 분리되어 있습니다. 채널은 리퍼러와 URL 파라미터(UTM)를 함께 확인합니다. 인스타그램·스레드 앱처럼 리퍼러를 숨기는 환경은 유입 링크의 채널별 복사 기능을 사용하면 자동으로 분류됩니다.</p><p>접수 시 서버가 국가·지역·시간대를 스냅샷으로 저장하고, 해당 시간대 기준의 접수 시각을 표시합니다. 위치 정보가 전달되지 않으면 확인 불가로 남습니다.</p><p>고객용 /consult는 공개 페이지이며 관리자 API는 승인된 직원만 사용할 수 있습니다.</p><a class="light" href="/consult" target="_blank">고객용 페이지 열기 ↗</a><h3 style="margin-top:24px">외부 서비스</h3><button class="light" id="checkMondaySettings">Monday 연결 확인</button><div id="mondaySettingsOutcome" aria-live="polite"></div><p>상담·결제 정보를 직원이 확인한 뒤 상담 상세의 ‘저장 후 Monday 전송’으로 반영합니다. 익명 접수는 서버에 저장되고 동기화 대기 상태가 됩니다. 상시 자동 동기화와 SNS 발송은 연결되지 않았습니다. 대상은 [TEST] AF DISTANCE 및 [TEST] 2026 REVENUE입니다. Distance에는 상담을 기록하고 Revenue에는 등록 완료 건만 반영합니다. 승인된 직원의 Monday 연결과 쓰기 동의가 필요합니다.</p></section><section class="panel"><h2>백업 및 기존 데이터</h2><button class="widebutton" id="backup">전체 데이터 JSON 내려받기 ↓</button><p>기존 브라우저에 저장된 문의는 자동으로 업로드하지 않습니다. 아래 버튼으로 확인 후 가져올 수 있습니다. 기존 문의에는 과거 마케터 정보를 임의로 부여하지 않습니다.</p><button class="light" id="importLocal">이 브라우저의 기존 문의 가져오기</button><p class="hint">자동 복원은 과거 실적을 덮어쓸 수 있어 지원하지 않습니다.</p></section></div>`}
function openModal(body){$('#modal').innerHTML=body;$('#modal').showModal();$('#closeModal')?.addEventListener('click',()=>$('#modal').close())}
function modalForm(title,fields,id='saveForm',submit='저장'){return `<form id="${id}"><div class="modalhead"><h2>${title}</h2><button type="button" class="ghost" id="closeModal" aria-label="닫기">✕</button></div>${fields}<div class="modalactions"><button type="submit" class="primary">${submit}</button></div></form>`}
const phoneCountries=[['KR','대한민국','82'],['US','미국','1'],['CA','캐나다','1'],['AU','호주','61'],['NZ','뉴질랜드','64'],['GB','영국','44'],['IE','아일랜드','353'],['JP','일본','81'],['CN','중국','86'],['HK','홍콩','852'],['TW','대만','886'],['SG','싱가포르','65'],['MY','말레이시아','60'],['VN','베트남','84'],['TH','태국','66'],['PH','필리핀','63'],['ID','인도네시아','62'],['IN','인도','91'],['AE','아랍에미리트','971'],['SA','사우디아라비아','966'],['DE','독일','49'],['FR','프랑스','33'],['ES','스페인','34'],['IT','이탈리아','39'],['NL','네덜란드','31'],['BE','벨기에','32'],['CH','스위스','41'],['AT','오스트리아','43'],['SE','스웨덴','46'],['NO','노르웨이','47'],['DK','덴마크','45'],['FI','핀란드','358'],['PL','폴란드','48'],['PT','포르투갈','351'],['TR','튀르키예','90'],['MX','멕시코','52'],['BR','브라질','55'],['ZA','남아프리카공화국','27']];
function normalizeContact(method,phone,country,kakao,customCode=''){
 if(method==='kakao'){const id=String(kakao||'').trim();if(!id||id.length>50||/[\s@]/.test(id))throw Error('카카오톡 아이디를 확인해 주세요. 이메일이나 공백은 입력할 수 없습니다.');return {contactType:'kakao',contact:'카카오톡 ID: '+id,kakaoId:id,country:null,callingCode:null,phone:null}}
 if(method!=='phone')throw Error('연락 방법을 선택해 주세요.');
 const selected=phoneCountries.find(c=>c[0]===country),code=country==='OTHER'?String(customCode).replace(/^\+/,''):selected?.[2];
 if(!code||!/^\d{1,3}$/.test(code)||code.startsWith('0'))throw Error('국가번호를 확인해 주세요.');
 const raw=String(phone||'').trim();if(!/^[\d ()-]+$/.test(raw))throw Error('전화번호는 숫자와 하이픈으로 입력해 주세요.');let number=raw.replace(/\D/g,'');if(country==='KR')number=number.replace(/^0/,'');if(number.length<6||number.length+code.length>15)throw Error('전화번호의 자릿수를 확인해 주세요.');
 return {contactType:'phone',contact:'+'+code+' '+number,country:country,callingCode:'+'+code,phone:number,kakaoId:null}
}
async function leadModal(visitorMode=false,interest=''){try{if(!residenceOptions)residenceOptions=await api('residence-options')}catch(e){toast('거주 지역 선택 목록을 불러오지 못했습니다. 다시 시도해 주세요.');return}const inquiryId=uuid();let courses=(data.published?.courses||data.page.courses);openModal(modalForm(visitorMode?'수강 상담 신청':'상담 추가',`<div class="banner" style="margin-top:15px">연락 가능한 정보를 남겨주시면 담당자가 수강 상담을 안내드립니다.</div><label for="leadName">이름 *</label><input id="leadName" name="name" maxlength="60" required><label for="contactMethod">연락 방법 *</label><select id="contactMethod" name="contactMethod"><option value="phone">전화번호</option><option value="kakao">카카오톡 아이디</option></select><div id="phoneFields"><label for="phoneCountry">전화 국가번호 *</label><select id="phoneCountry" name="country">${phoneCountries.map(c=>`<option value="${c[0]}">${c[1]} (+${c[2]})</option>`).join('')}<option value="OTHER">기타 국가 · 국가번호 직접 입력</option></select><div id="customCodeFields" hidden><label for="customCallingCode">국가번호 *</label><input id="customCallingCode" name="customCode" inputmode="numeric" placeholder="예: 82" pattern="[+]?[1-9][0-9]{0,2}" maxlength="4" disabled></div><label for="leadPhone">전화번호 *</label><input id="leadPhone" name="phone" type="tel" inputmode="tel" autocomplete="tel-national" required maxlength="25" placeholder="예: 010-1234-5678"><p class="hint">선택한 국가번호를 제외한 전화번호를 입력해 주세요.</p></div><div id="kakaoFields" hidden><label for="leadKakao">카카오톡 아이디 *</label><input id="leadKakao" name="kakaoId" maxlength="50" autocomplete="off" placeholder="카카오톡 아이디 입력" pattern="[^\\s@]+" disabled><p class="hint" id="kakaoNotice">카카오톡 ‘ID 검색 허용’이 꺼져 있으면 아이디 검색과 상담 안내가 어렵습니다. 카카오톡 설정에서 ID 검색을 허용해 주세요.</p></div>${residenceForm()}<label for="leadCourse">관심 코스</label><select id="leadCourse" name="course">${courses.map(c=>`<option ${c.name===interest?'selected':''}>${esc(c.name)}</option>`).join('')}<option>상담 후 결정</option></select><label for="leadSource">유입 경로 *</label><select id="leadSource" name="source" required><option value="" selected>선택</option>${['인스타그램','스레드','블로그','유튜브','지인 소개','카톡 오픈채팅','네이버카페','기타'].map(c=>`<option value="${esc(c)}">${esc(c==='네이버카페'?'네이버 카페':c)}</option>`).join('')}</select><div id="sourceOtherFields" hidden><label for="leadSourceDetail">유입 경로 직접 입력 *</label><input id="leadSourceDetail" name="sourceDetail" maxlength="100" placeholder="어디에서 알게 되셨는지 입력해 주세요." disabled></div><label for="leadMessage">문의 내용</label><textarea id="leadMessage" name="message" maxlength="2000" placeholder="관심 있는 과정이나 궁금한 점을 적어 주세요."></textarea><div class="consent-summary"><strong>개인정보 수집·이용 안내</strong><p>수집 항목: 이름, 전화번호(국가번호 포함) 또는 카카오톡 아이디, 거주 국가·주/도(지역)·시간대, 관심 코스, 유입 경로 및 링크 식별 정보, 방문 출처 사이트, 문의 내용<br>이용 목적: 수강 상담 안내 및 문의 답변<br>동의를 거부할 수 있으나, 동의하지 않으면 상담을 신청할 수 없습니다.</p></div><label class="checkrow"><input id="contactConsent" name="consent" type="checkbox" value="yes" required><span>[필수] 위 내용을 확인했으며, 입력한 정보를 상담 안내 및 답변을 위해 수집·이용하는 데 동의합니다.</span></label>`,'saveLead',visitorMode?'상담 신청하기':'상담 저장'));
 function syncContactFields(){const isPhone=$('#contactMethod').value==='phone',other=isPhone&&$('#phoneCountry').value==='OTHER';$('#phoneFields').hidden=!isPhone;$('#kakaoFields').hidden=isPhone;$('#phoneCountry').disabled=!isPhone;$('#leadPhone').disabled=!isPhone;$('#leadPhone').required=isPhone;$('#leadKakao').disabled=isPhone;$('#leadKakao').required=!isPhone;$('#customCodeFields').hidden=!other;$('#customCallingCode').disabled=!other;$('#customCallingCode').required=other}
 const sourceDetail=$('#leadSourceDetail');function syncSourceFields(){const other=$('#leadSource').value==='기타';$('#sourceOtherFields').hidden=!other;sourceDetail.disabled=!other;sourceDetail.required=other;sourceDetail.setCustomValidity(other&&!sourceDetail.value.trim()?'유입 경로를 직접 입력해 주세요.':'')}$('#leadSource').onchange=syncSourceFields;sourceDetail.oninput=syncSourceFields;syncSourceFields();
 setupResidenceForm();
 $('#contactMethod').onchange=syncContactFields;$('#phoneCountry').onchange=syncContactFields;syncContactFields();
 $('#saveLead').onsubmit=async e=>{e.preventDefault();if(!e.target.checkValidity()){e.target.reportValidity();return}let f=new FormData(e.target);if(f.get('consent')!=='yes'){toast('정보 수집·이용 동의는 필수입니다.');return}let contact;try{contact=normalizeContact(f.get('contactMethod'),f.get('phone'),f.get('country'),f.get('kakaoId'),f.get('customCode'))}catch(error){toast(error.message);return}const name=String(f.get('name')||'').trim();if(!name){toast('이름을 입력해 주세요.');return}let timezone='';try{timezone=Intl.DateTimeFormat().resolvedOptions().timeZone||''}catch{}const lead={id:inquiryId,name,...contact,consent:{accepted:true},source:f.get('source'),sourceDetail:f.get('sourceDetail'),course:f.get('course'),message:f.get('message'),manual:!visitorMode,timezone,residence:readResidenceForm()};const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await api('inquiries','POST',lead);if(!visitorMode)await refreshState();$('#modal').close();toast('상담 신청이 접수되었습니다.');}catch(error){toast(error.message);button.disabled=false;return}if(!visitorMode)render()}}

function ruleModal(id){let r=data.rules.find(x=>x.id===id)||{keyword:'',reply:'',enabled:true};openModal(modalForm(id?'규칙 편집':'응답 규칙 추가',`<label for="ruleKeywords">키워드 · 쉼표로 구분</label><input id="ruleKeywords" name="keyword" required maxlength="300" value="${esc(r.keyword)}" placeholder="예: 클래스,수강료"><label for="ruleReply">응답 문구</label><textarea id="ruleReply" name="reply" required maxlength="2000">${esc(r.reply)}</textarea>`));$('#saveForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),item={...r,id:id||uuid(),keyword:f.get('keyword').split(',').map(s=>s.trim()).filter(Boolean).join(','),reply:f.get('reply').trim()};if(!item.keyword||!item.reply){toast('키워드와 응답을 입력해 주세요.');return}if(id)data.rules=data.rules.map(x=>x.id===id?item:x);else data.rules.push(item);try{await save()}catch(error){toast(error.message);return}$('#modal').close();render();toast('응답 규칙을 저장했습니다.')}}
function download(name,content,type){let url=URL.createObjectURL(new Blob([content],{type}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function patchLead(l,changes){const result=await api('admin/leads','PATCH',{id:l.id,opsRevision:l.opsRevision||0,...changes});Object.assign(l,result.lead);await refreshState();return data.leads.find(x=>x.id===l.id)}
function orderedLeads(){const rank=new Map(leadOrder.map((id,i)=>[id,i]));return filteredLeads().slice().reverse().sort((a,b)=>(rank.get(a.id)??-1)-(rank.get(b.id)??-1))}
async function moveLead(source,target){if(!source||source===target)return;const ids=data.leads.slice().reverse().sort((a,b)=>(leadOrder.indexOf(a.id)<0?-1:leadOrder.indexOf(a.id))-(leadOrder.indexOf(b.id)<0?-1:leadOrder.indexOf(b.id))).map(l=>l.id);const downward=ids.indexOf(source)<ids.indexOf(target);ids.splice(ids.indexOf(source),1);ids.splice(ids.indexOf(target)+(downward?1:0),0,source);try{await api('admin/lead-order','POST',{ids,revision:orderRevision});await refreshState();$('#leadRows').innerHTML=leadRows();bindLeadRows();toast('상담 순서를 저장했습니다.')}catch(e){toast(e.message);await refreshState();render()}}
function leadTrash(){openModal(`<div class="modalhead"><h2>삭제한 상담</h2><button id="closeModal" class="ghost">✕</button></div><p class="hint">복원하면 상담 목록에 다시 표시됩니다. Monday에 반영된 기록은 유지됩니다.</p>${deletedLeads.map(l=>`<div class="row"><strong>${esc(l.name)}</strong><button class="light" data-restore-lead="${esc(l.id)}">복원</button></div>`).join('')||'<p>삭제한 상담이 없습니다.</p>'}`);document.querySelectorAll('[data-restore-lead]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await patchLead(deletedLeads.find(l=>l.id===b.dataset.restoreLead),{deleted:false});leadTrash();render()}catch(e){toast(e.message);b.disabled=false}})}
function bindLeadRows(){
 $('#showLeadTrash')?.addEventListener('click',leadTrash);
 document.querySelectorAll('[data-delete-lead]').forEach(b=>b.onclick=()=>{const l=data.leads.find(l=>l.id===b.dataset.deleteLead);openModal(modalForm('상담 삭제',`<p>${esc(l.name)}님의 상담을 삭제함으로 이동합니다. 삭제함에서 복원할 수 있습니다.</p><p class="hint">Monday에 이미 전송한 기록은 유지됩니다.</p>`,'deleteLeadForm','삭제'));$('#deleteLeadForm').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await patchLead(l,{deleted:true});$('#modal').close();render();toast('상담을 삭제함으로 이동했습니다.')}catch(error){toast(error.message);e.submitter.disabled=false}}});
 document.querySelectorAll('[data-drag-lead]').forEach(b=>{b.ondragstart=e=>{dragLeadId=b.dataset.dragLead;e.dataTransfer.setData('text/plain',dragLeadId);e.dataTransfer.effectAllowed='move'};b.ondragend=()=>{dragLeadId=null};b.onkeydown=e=>{if(!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const ids=orderedLeads().map(l=>l.id),i=ids.indexOf(b.dataset.dragLead),target=ids[i+(e.key==='ArrowUp'?-1:1)];if(target)moveLead(b.dataset.dragLead,target)}});
 document.querySelectorAll('[data-lead-row]').forEach(row=>{row.ondragover=e=>{if(dragLeadId){e.preventDefault();e.dataTransfer.dropEffect='move'}};row.ondrop=e=>{e.preventDefault();const source=dragLeadId;dragLeadId=null;moveLead(source,row.dataset.leadRow)}});
document.querySelectorAll('[data-status]').forEach(el=>el.onchange=async()=>{const l=data.leads.find(l=>l.id===el.dataset.status);el.disabled=true;try{await patchLead(l,{status:el.value});$('#leadRows').innerHTML=leadRows();bindLeadRows();toast('상담 상태를 저장했습니다. Monday 반영은 동기화 대기입니다.')}catch(e){el.value=l.status;toast(e.message)}finally{el.disabled=false}});document.querySelectorAll('[data-detail]').forEach(el=>el.onclick=()=>leadDetail(data.leads.find(x=>x.id===el.dataset.detail)))}
function field(name,title,value='',type='text'){return `<label for="op-${name}">${title}</label><input id="op-${name}" name="${name}" type="${type}" ${type==='number'?'min="0" max="10000000000" step="1"':''} maxlength="${['availability','preferredSchedule'].includes(name)?500:150}" value="${esc(value)}">`}
function leadDetail(l){const o=op(l),sy=syncInfo(l);openModal(modalForm('상담 · 결제 관리',`<div class="lead-detail-heading"><h3>${esc(l.name)} · ${esc(l.course)}</h3><p>${esc(l.contact)}</p><p class="hint">상담 ID ${esc(l.id)}<br>접수: ${esc(l.submittedAt||l.createdAt)} UTC<br>접수 당시 마케터: ${esc(l.marketerName||'미배정')} · ${esc(l.referralChannel||l.source)}${l.sourceDetail?' · '+esc(l.sourceDetail):''}<br>고객 입력 거주지: ${esc(l.residence?[l.residence.country,l.residence.region,l.residence.city].filter(Boolean).join(' / '):'기존 접수 · 고객 입력 없음')}<br>고객 선택 시간대: ${esc(l.residence?.timezone||'기존 접수 · 미입력')}<br>자동 감지 접속 위치: ${esc(leadLocation(l))} / ${esc(l.locationTimezone||'확인 불가')}</p></div><h3>상담 및 거주 정보</h3><label for="op-status">상담 상태</label><select id="op-status" name="status">${consultationStates.map(s=>`<option ${l.status===s?'selected':''}>${s}</option>`).join('')}</select><div class="operation-grid">${field('guardianName','보호자명',o.guardianName)}${field('country','거주 국가',o.country)}${field('region','거주 지역 / 주',o.region)}</div><label for="op-timezone">고객 시간대 ID</label><input name="timezone" id="op-timezone" list="timezones" value="${esc(o.timezone)}" placeholder="예: America/Los_Angeles"><datalist id="timezones">${['Asia/Seoul','America/Los_Angeles','America/New_York','America/Chicago','America/Denver','Pacific/Honolulu','America/Toronto','America/Vancouver','Europe/London','Europe/Dublin','Australia/Sydney','Australia/Brisbane','Australia/Perth','Pacific/Auckland','Asia/Tokyo','Asia/Singapore','Asia/Dubai'].map(t=>`<option value="${t}">`).join('')}</datalist><p class="hint">입력하지 않으면 접수 때 감지한 시간대를 사용합니다. 실제 거주 시간대인지 확인해 주세요.</p>${field('availability','연락 가능한 시간 · 고객 현지 기준',o.availability)}<div class="operation-grid">${field('device','보유 기기',o.device)}${field('preferredSchedule','클래스 희망 일정',o.preferredSchedule)}</div>${field('confirmedCurriculum','클래스 · 확정 코스',o.confirmedCurriculum)}<h3 style="margin-top:28px">수업 인계 · 전환 이력</h3><div class="operation-grid">${field('studentName','수강생명',o.studentName||l.name)}${field('classSchedule','수업일정 · 시간대 포함',o.classSchedule)}${field('instructor','담당강사',o.instructor)}${field('specialNotes','특이사항',o.specialNotes)}${field('studentDBId','학생 DB 아이템 ID',o.studentDBId)}${field('trialDate','트라이얼 실제 참여일',o.trialDate,'date')}${field('enrollmentDate','정규 등록일',o.enrollmentDate,'date')}${field('renewalDate','재등록일',o.renewalDate,'date')}</div><p class="hint">실제 참여·등록이 확인된 날짜만 입력해 주세요. 동일 학생 DB ID로 중복을 제외해 추적합니다.</p><button type="button" class="light" id="copyHandoff" aria-label="인포 허브 메모 복사" title="인포 허브 메모 복사">⧉</button><h3 style="margin-top:28px">결제 정보</h3><label for="op-paymentStatus">결제 상태</label><select id="op-paymentStatus" name="paymentStatus">${paymentStates.map(s=>`<option ${o.paymentStatus===s?'selected':''}>${s}</option>`).join('')}</select><div class="operation-grid">${field('amount','총 비용 (원)',o.amount,'number')}${field('paidAmount','실입금액 (원)',o.paidAmount,'number')}${field('paymentMethod','결제 방식',o.paymentMethod)}${field('payerName','결제자명',o.payerName)}${field('paymentEmail','결제 이메일',o.paymentEmail,'email')}${field('paymentDate','결제일',o.paymentDate,'date')}</div><label for="op-commissionRate">Revenue 커미션 비율</label><select id="op-commissionRate" name="commissionRate"><option value="10" ${o.commissionRate===10?'selected':''}>10% · 기본</option><option value="20" ${o.commissionRate===20?'selected':''}>20% · 기존 체크박스 적용</option></select><p class="hint">전액 확인은 CLEAR, 부분 결제는 SPLIT로 반영하며 Revenue 비용에는 실제 입금액을 전달합니다. 커미션은 Revenue의 기존 계산식을 사용합니다. 취소·환불은 기존 매출을 자동 삭제하거나 변경하지 않습니다.</p><label for="leadNote">상담 메모</label><textarea id="leadNote" name="note" maxlength="3000">${esc(l.note)}</textarea><div class="ops-sync-box"><strong>Monday 전송 상태</strong>${syncBoards(l,true)}${sy.error?`<p class="banner">${esc(sy.error)}</p>`:''}<div class="actions"><button type="button" class="light" id="saveThenSync">저장 후 Monday 전송</button><button type="button" class="ghost" id="archiveLead">${l.archived?'보관 해제':'보관하기'}</button><button type="button" class="ghost" id="leadHistory">변경 이력</button></div></div>`,'saveOperations','사이트에 저장'));
 $('#copyHandoff').onclick=async()=>{const f=Object.fromEntries(new FormData($('#saveOperations')));const text=`수강생명 : ${f.studentName||''}\n수업일정 : ${f.classSchedule||''}\n클래스 : ${f.confirmedCurriculum||''}\n담당강사 : ${f.instructor||''}\n특이사항 : ${f.specialNotes||''}`;try{await navigator.clipboard.writeText(text);toast('인포 허브용 정보를 복사했습니다.')}catch{openModal(`<div class=modalhead><h2>인포 허브 메모</h2><button id=closeModal>✕</button></div><textarea id=handoffCopy readonly>${esc(text)}</textarea>`);$('#handoffCopy').select()}};
 const persist=async(shouldSync=false)=>{const form=$('#saveOperations');if(!form.checkValidity()){form.reportValidity();return null}const f=Object.fromEntries(new FormData(form)),operations={};for(const key of Object.keys(o))if(f[key]!==undefined)operations[key]=['amount','paidAmount','commissionRate'].includes(key)?Number(f[key]):f[key];return patchLead(l,{status:f.status,note:f.note,operations,sync:shouldSync})};
 $('#saveOperations').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;try{const latest=await persist();if(latest){$('#modal').close();render();toast('사이트에 저장했습니다. Monday 동기화 대기입니다.')}}catch(e){toast(e.message)}finally{btn.disabled=false}};
 $('#saveThenSync').onclick=async e=>{e.target.disabled=true;try{const latest=await persist();if(latest)syncModal(latest);else e.target.disabled=false}catch(e){toast(e.message);e.target.disabled=false}};
 $('#archiveLead').onclick=async e=>{e.target.disabled=true;try{await patchLead(l,{archived:!l.archived});$('#modal').close();render();toast(l.archived?'보관했습니다. 과거 실적은 유지됩니다.':'보관을 해제했습니다.')}catch(e){toast(e.message);e.target.disabled=false}};
 $('#leadHistory').onclick=async()=>{try{const r=await api('admin/lead-history','POST',{id:l.id});openModal(`<div class="modalhead"><h2>상담 변경 이력</h2><button class="ghost" id="closeModal">✕</button></div>${r.history.map(h=>{const a=JSON.parse(h.after_json);return `<div class="row"><div><strong>${esc(h.at)}</strong><p class="hint">${esc(h.actor)} · ${esc(a.status)} · ${esc(a.operations?.paymentStatus||'결제 대기')} · ${a.archived?'보관':'운영 중'}</p><details><summary>변경 내용</summary><pre style="white-space:pre-wrap">${esc(h.after_json)}</pre></details></div></div>`}).join('')||'<p>변경 이력이 없습니다.</p>'}`)}catch(e){toast(e.message)}};
}
function syncModal(l){const sy=syncInfo(l);openModal(modalForm('Monday 반영 확인',`<p class="hint">${esc(l.name)}님의 연락처·상담·결제 정보를 아래 보드로 전송합니다. 최초에는 새 아이템을 만들고, 연결된 이후에는 같은 아이템을 갱신합니다.</p><div class="ops-sync-box"><strong>[TEST] AF DISTANCE</strong><p class="hint">${esc(l.date.slice(0,7))} 월별 메인 아이템 아래 고객 하위 아이템<br>사이트 상담 ID와 Monday 아이템 ID 연결</p><strong>[TEST] 2026 REVENUE</strong><p class="hint">등록 완료 건만 반영합니다. 미입금 등록은 DUE로 기록합니다.</p>${syncBoards(l,true)}</div><label class="checkrow"><input type="checkbox" name="confirm" required><span>해당 고객의 저장된 상담·결제 정보를 위 Monday 보드에 기록하는 데 동의합니다.</span></label><div class="actions"><button type="button" class="light" id="checkMondayConnection">연결만 확인</button></div><p class="hint">연결 확인은 보드 구조만 읽으며 상담·결제 기록을 생성하거나 수정하지 않습니다.</p><div id="mondayOutcome" aria-live="polite"></div>${['review','running'].includes(sy.state)?'<button type="button" class="light" id="reviewSync">기존 아이템 ID 확인 · 연결</button>':''}`,'syncLeadForm','Monday에 반영'));
 $('#checkMondayConnection').onclick=()=>checkMondayConnection('mondayOutcome','#syncLeadForm [type=submit]');
 $('#syncLeadForm').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;try{const r=await api('admin/monday/sync','POST',{id:l.id,opsRevision:l.opsRevision||0,confirm:true});await refreshState();$('#modal').close();render();toast(r.summary||'Monday에 반영했습니다.')}catch(e){$('#mondayOutcome').innerHTML=`<div class="banner">${esc(e.message)}${e.details?.signInUrl?`<p><a href="${esc(e.details.signInUrl)}" target="_top">Monday 연결을 위해 로그인</a></p>`:''}</div>`;await refreshState().catch(()=>{});btn.disabled=e.details?.provider?.status==='binding_unavailable'||e.details?.provider?.status==='connector_access_disabled'}};
 $('#reviewSync')?.addEventListener('click',()=>reconcileModal(l));
}
function reconcileModal(l){const sy=syncInfo(l);openModal(modalForm('전송 결과 확인 · 연결',`<p class="hint">전송 중 연결이 끊겼을 때 중복 생성을 막기 위해 자동 재시도를 중지합니다. 보드에서 생성된 아이템을 확인한 뒤 ID를 입력하세요. 상담 식별자 [AU:${esc(l.id)}]가 일치하는 아이템만 연결됩니다. 연결 확인은 읽기 작업이며 아이템을 생성하지 않습니다.</p>${field('distanceId','Distance 고객 하위 아이템 ID',sy.distance_id||'')}${field('revenueId','Revenue 아이템 ID · 생성된 경우',sy.revenue_id||'')}<div id="reconcileOutcome" aria-live="polite"></div>`,'reconcileForm','ID 확인 및 연결'));$('#reconcileForm').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await api('admin/monday/reconcile','POST',{id:l.id,...Object.fromEntries(new FormData(e.target))});await refreshState();$('#modal').close();render();toast('기존 아이템 연결을 확인했습니다. 다시 동기화할 수 있습니다.')}catch(error){$('#reconcileOutcome').textContent=error.message;e.submitter.disabled=false}}}
function bind(){document.querySelectorAll('[data-go]').forEach(el=>el.onclick=()=>{current=el.dataset.go;shell()});$('#newLead')?.addEventListener('click',()=>leadModal());if(current==='page')bindEditor();if(current==='leads'){$('#reloadLeads').onclick=async()=>{try{await refreshState();render()}catch(e){toast(e.message)}};document.querySelectorAll('[data-lead-filter]').forEach(el=>{el.oninput=el.onchange=()=>{$('#leadRows').innerHTML=leadRows();bindLeadRows()}});bindLeadRows();$('#exportLeads').onclick=()=>{const cell=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';let rows=[['이름','연락처','코스','유입 경로','접수일시','국가','지역','도시','시간대','상태','문의','메모','유입 링크','접수 당시 마케터','감지된 채널','감지 방식','유입 파라미터','출처 사이트','결제 상태','총 비용','실입금액','결제일','결제자명','결제 이메일','보관 상태','Monday 상태'],...data.leads.map(l=>[l.name,l.contact,l.course,l.source+(l.sourceDetail?' · '+l.sourceDetail:''),formatLeadDate(l),l.locationCountry,l.locationRegion,l.locationCity,l.locationTimezone,l.status,l.message,l.note,l.referralCode,l.marketerName,l.referralChannel,l.channelMethod,l.attributionParam,l.referrerHost,op(l).paymentStatus,op(l).amount,op(l).paidAmount,op(l).paymentDate,op(l).payerName,op(l).paymentEmail,l.archived?'보관':'운영 중',syncLabel(l)])];download('affinity-consultations.csv','\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}}if(current==='rules'){$('#newRule').onclick=()=>ruleModal();document.querySelectorAll('[data-edit-rule]').forEach(e=>e.onclick=()=>ruleModal(e.dataset.editRule));document.querySelectorAll('[data-toggle-rule]').forEach(e=>e.onclick=async()=>{let r=data.rules.find(r=>r.id===e.dataset.toggleRule);r.enabled=!r.enabled;try{await save();render()}catch(error){toast(error.message)}});$('#testReply').onclick=()=>{let message=$('#testMessage').value.trim();if(!message){toast('테스트할 메시지를 입력해 주세요.');return}let r=data.rules.find(r=>r.enabled&&r.keyword.split(',').some(k=>k.trim()&&message.toLowerCase().includes(k.trim().toLowerCase())));$('#replyResult').innerHTML=r?`<div class="bubble">${esc(r.reply)}</div><span class="pill">일치 규칙: ${esc(r.keyword)}</span><p class="hint">테스트 결과입니다. 메시지는 발송되지 않았습니다.</p>`:'<div class="empty" style="margin-top:20px">일치하는 활성 규칙이 없습니다. 수동 상담으로 연결하세요.</div>'}}if(current==='links')bindLinks();if(current==='settings'){$('#checkMondaySettings').onclick=()=>checkMondayConnection('mondaySettingsOutcome');$('#backup').onclick=async()=>{try{await refreshLinks();await refreshState();download('affinity-studio-backup.json',JSON.stringify({...data,...linkData},null,2),'application/json')}catch(e){toast(e.message)}};$('#importLocal').onclick=()=>importLocal()}}
function validateBackup(x){const str=v=>typeof v==='string',page=p=>p&&str(p.title)&&str(p.description)&&Array.isArray(p.courses)&&p.courses.length<=40&&p.courses.every(c=>str(c.name)&&str(c.description));if(!x||!page(x.page)||(x.published!==null&&!page(x.published))||!Array.isArray(x.leads)||!Array.isArray(x.rules)||!Array.isArray(x.posts)||!Array.isArray(x.events)||!x.leads.every(l=>['id','name','contact','course','source','date','status','message'].every(k=>str(l[k]))&&['신규 문의','상담 중','등록 완료','보류'].includes(l.status))||!x.rules.every(r=>str(r.id)&&str(r.keyword)&&str(r.reply)&&typeof r.enabled==='boolean')||!x.posts.every(p=>['id','title','date','body','channel','status'].every(k=>str(p[k])))||!x.events.every(e=>str(e.type)))throw Error('invalid')}
function visitor(){let p=data.published||initial.page;$('#app').innerHTML=`<main class="visitor">${phone(p,true)}<p class="hint" style="text-align:center;margin-top:20px">AFFINITY UNIVERSE</p></main>`;$('#requestConsult').onclick=()=>leadModal(true);document.querySelectorAll('[data-interest]').forEach(b=>b.onclick=()=>leadModal(true,p.courses[Number(b.dataset.interest)].name))}
async function refreshState(){const result=await api('admin/state');if(result.config){Object.assign(data,result.config)}revision=result.revision;data.leads=result.leads;deletedLeads=result.trash||[];leadOrder=result.leadOrder||[];orderRevision=result.orderRevision??-1;syncData=result.syncs||[];totalVisits=result.visits}
async function refreshLinks(){linkData=await api('admin/links')}
async function boot(){try{const result=await api('public');isAdmin=result.admin;if(result.page)data.published=result.page;if(customerView()){let timezone='';try{timezone=Intl.DateTimeFormat().resolvedOptions().timeZone||''}catch{}await api('visit','POST',{code:new URLSearchParams(location.search).get('ref')||'',referrer:document.referrer,landingUrl:location.href,timezone});visitor()}else if(isAdmin){await refreshState();await refreshLinks();shell()}else{location.replace('/consult')}}catch(e){$('#app').innerHTML=`<main class="visitor"><h1>불러오지 못했습니다.</h1><p>${esc(e.message)}</p><button class="light" onclick="location.reload()">다시 시도</button></main>`}}
window.addEventListener('hashchange',()=>{if(customerView())boot();else shell()});boot();
function linksView(){return heading('같은 페이지, 정확한 유입 기록.','링크마다 담당 마케터를 배정하고 접수 당시의 실적을 보존합니다.',`<div class="actions"><button class="light" id="newMarketer">+ 마케터</button><button class="primary" id="newLink">+ 유입 링크</button></div>`)+`<div class="banner">퇴사 시: 활성 링크를 새 담당자에게 재배정하거나 비활성화한 후 마케터를 퇴사 처리하세요. 비활성 링크도 고객 페이지는 열리며 신규 문의에는 마케터가 배정되지 않습니다.</div><section class="panel"><div class="panelhead"><h2>유입 링크</h2><button class="light" id="reloadLinks">새로고침</button></div><div class="tablewrap"><table><thead><tr><th>유입 링크</th><th>현재 마케터</th><th>상태</th><th>방문</th><th>문의 / 등록</th><th>관리</th></tr></thead><tbody>${linkData.links.map(l=>{const ls=data.leads.filter(x=>x.referralCode===l.code);return `<tr><td><strong>${esc(l.label)}</strong><p class="hint">${esc(l.code)} · 마케터 고유 링크 · 유입 경로는 고객 필수 선택</p></td><td>${esc(linkData.marketers.find(m=>m.id===l.marketer_id)?.name||'미배정')}</td><td><span class="pill ${l.active?'':'gray'}">${l.active?'활성':'비활성'}</span></td><td>${l.visits}</td><td>${ls.length} / ${ls.filter(x=>x.status==='등록 완료').length}</td><td><div class="actions"><button class="light" data-copy-link="${l.id}">링크 복사</button><button class="ghost" data-edit-link="${l.id}">수정 · 재배정</button><button class="ghost" data-link-history="${l.id}">이력</button></div></td></tr>`}).join('')||'<tr><td colspan="6">마케터를 추가하고 첫 유입 링크를 만들어 주세요.</td></tr>'}</tbody></table></div><p class="hint">유입 경로는 고객이 상담 신청 시 필수로 선택합니다. 문의·등록은 링크의 전체 이력이며 아래 마케터별 실적은 접수 당시 배정을 기준으로 계산합니다.</p></section><section class="panel" style="margin-top:24px"><h2>마케터별 문의 · 등록 실적</h2><div class="tablewrap"><table><thead><tr><th>마케터</th><th>상태</th><th>문의</th><th>등록 완료</th><th>문의 → 등록 전환율</th><th>관리</th></tr></thead><tbody>${linkData.marketers.map(m=>{const ls=data.leads.filter(l=>l.marketerId===m.id),n=ls.filter(l=>l.status==='등록 완료').length;return `<tr><td>${esc(m.name)}</td><td>${m.active?'활성':'퇴사 / 비활성'}</td><td>${ls.length}</td><td>${n}</td><td>${ls.length?(n/ls.length*100).toFixed(1):'0.0'}%</td><td><button class="ghost" data-edit-marketer="${m.id}">이름 · 상태 수정</button></td></tr>`}).join('')||'<tr><td colspan="6">등록된 마케터가 없습니다.</td></tr>'}</tbody></table></div></section>`}
function bindLinks(){
 $('#newMarketer').onclick=()=>marketerModal();$('#newLink').onclick=()=>linkModal();$('#reloadLinks').onclick=async()=>{try{await refreshLinks();await refreshState();render()}catch(e){toast(e.message)}};
 document.querySelectorAll('[data-edit-marketer]').forEach(b=>b.onclick=()=>marketerModal(b.dataset.editMarketer));
 document.querySelectorAll('[data-edit-link]').forEach(b=>b.onclick=()=>linkModal(b.dataset.editLink));
 document.querySelectorAll('[data-copy-link]').forEach(b=>b.onclick=async()=>{const l=linkData.links.find(x=>x.id===b.dataset.copyLink),url=location.origin+'/consult?ref='+l.code;try{await navigator.clipboard.writeText(url);toast('고객용 유입 링크를 복사했습니다.')}catch{openModal(`<div class="modalhead"><h2>고객용 유입 링크</h2><button class="ghost" id="closeModal">✕</button></div><label for="copyUrl">복사할 주소</label><input id="copyUrl" readonly value="${esc(url)}">`);$('#copyUrl').select()}});
 document.querySelectorAll('[data-link-history]').forEach(b=>b.onclick=()=>{const rows=linkData.history.filter(h=>h.link_id===b.dataset.linkHistory);openModal(`<div class="modalhead"><h2>링크 변경 이력</h2><button class="ghost" id="closeModal">✕</button></div>${rows.map(h=>{const before=h.before_json?JSON.parse(h.before_json):null,after=JSON.parse(h.after_json),name=v=>linkData.marketers.find(m=>m.id===v?.marketer_id)?.name||'없음';return `<div class="row"><div><strong>${before?'수정':'신규 생성'} · ${esc(after.active?'활성':'비활성')}</strong><p>${esc(name(before))} → ${esc(name(after))}</p><small>${esc(new Date(h.at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}))} KST<br>${esc(h.actor)}</small></div></div>`}).join('')||'<p>변경 이력이 없습니다.</p>'}`)});
}
function marketerModal(id){const m=linkData.marketers.find(x=>x.id===id);openModal(modalForm(m?'마케터 수정':'마케터 추가',`<label for="marketerName">이름 *</label><input id="marketerName" name="name" required maxlength="100" value="${esc(m?.name||'')}">${m?`<label for="marketerActive">상태</label><select id="marketerActive" name="active"><option value="1" ${m.active?'selected':''}>활성</option><option value="0" ${!m.active?'selected':''}>퇴사 / 비활성</option></select><p class="hint">퇴사 처리 전 활성 링크를 재배정하거나 비활성화해 주세요. 과거 문의의 이름과 실적은 유지됩니다.</p>`:''}`));$('#saveForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),btn=e.target.querySelector('[type=submit]');btn.disabled=true;try{await api('admin/marketers',m?'PATCH':'POST',{id,name:f.get('name'),active:m?f.get('active')==='1':true});await refreshLinks();$('#modal').close();render();toast('마케터를 저장했습니다.')}catch(error){toast(error.message);btn.disabled=false}}}
function linkModal(id){const l=linkData.links.find(x=>x.id===id);if(!l&&!linkData.marketers.some(m=>m.active)){toast('활성 마케터를 먼저 추가해 주세요.');return}openModal(modalForm(l?'링크 수정 · 담당자 재배정':'유입 링크 생성',`<label for="linkLabel">링크 이름 *</label><input id="linkLabel" name="label" required maxlength="100" placeholder="예: 마케터 A 대표 링크" value="${esc(l?.label||'')}"><p class="hint">이 링크는 여러 채널에서 사용할 수 있습니다. 상담 신청 시 고객이 유입 경로를 선택합니다.</p><label for="linkMarketer">담당 마케터 *</label><select name="marketer_id" id="linkMarketer">${linkData.marketers.filter(m=>m.active||m.id===l?.marketer_id).map(m=>`<option value="${esc(m.id)}" ${m.id===l?.marketer_id?'selected':''}>${esc(m.name)}${m.active?'':' (퇴사)'}</option>`).join('')}</select><label for="linkActive">링크 상태</label><select name="active" id="linkActive"><option value="1" ${!l||l.active?'selected':''}>활성</option><option value="0" ${l&&!l.active?'selected':''}>비활성</option></select><p class="hint">${l?'주소는 유지되며 저장 후 접수되는 문의부터 새 배정이 적용됩니다. 이전 문의의 마케터와 실적은 바뀌지 않습니다.':'무작위 코드를 사용하는 고객용 주소를 발급합니다. 고객 화면에 마케터 정보는 표시하지 않습니다.'}</p>`));$('#saveForm').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('[type=submit]'),f=new FormData(e.target);btn.disabled=true;try{await api('admin/links',l?'PATCH':'POST',{...Object.fromEntries(f),id,revision:l?.revision,active:f.get('active')==='1'});await refreshLinks();$('#modal').close();render();toast('유입 링크를 저장했습니다.')}catch(error){toast(error.message);btn.disabled=false}}}
async function importLocal(){let old;try{old=JSON.parse(localStorage.getItem(KEY));validateBackup(old)}catch{toast('이 브라우저에 가져올 기존 문의가 없습니다.');return}const pending=old.leads.filter(l=>!data.leads.some(x=>x.id===l.id));openModal(`<div class="modalhead"><h2>기존 문의 가져오기</h2><button class="ghost" id="closeModal">✕</button></div><p>이 브라우저의 기존 문의 ${pending.length}건을 서버에 추가합니다. 기존 원본은 유지됩니다. 동의 정보와 지원되는 연락처가 있는 문의만 가져옵니다.</p><button class="primary" id="confirmImport">가져오기</button>`);$('#confirmImport').onclick=async e=>{e.target.disabled=true;let count=0;try{for(const l of pending){if(!l.consent?.accepted||!['phone','kakao'].includes(l.contactType))continue;await api('inquiries','POST',{...l,manual:true,imported:true});count++}await refreshState();$('#modal').close();toast(`${count}건을 가져왔습니다. 연락처·동의 정보를 확인할 수 없는 문의는 원본에 남아 있습니다.`)}catch(error){toast(error.message);e.target.disabled=false}}}
function readEditorInputs(){if(!$('#pageTitle'))return;data.page.title=$('#pageTitle').value;data.page.description=$('#pageDesc').value;data.page.courses.forEach((c,i)=>{c.name=$('#cn'+i).value;c.description=$('#cd'+i).value})}
function editorState(text){if($('#editorSaveState'))$('#editorSaveState').textContent=text}
function editorBusy(busy){document.querySelectorAll('#content input,#content textarea,#content button,[data-nav],#previewBtn').forEach(el=>{if(busy){el.dataset.wasDisabled=String(el.disabled);el.disabled=true}else if(el.dataset.wasDisabled!==undefined){el.disabled=el.dataset.wasDisabled==='true';delete el.dataset.wasDisabled}})}
async function changeCourses(change){clearTimeout(window.draftTimer);readEditorInputs();const previous=structuredClone(data.page);editorBusy(true);try{change();await save();if(current==='page')render();toast('코스 구성을 저장했습니다.')}catch(e){data.page=previous;toast(e.message);editorState('저장하지 못했습니다. '+e.message)}finally{editorBusy(false)}}
function bindEditor(){
 $('#pageTitle').oninput=$('#pageDesc').oninput=()=>updateDraft();document.querySelectorAll('[data-course-name],[data-course-desc]').forEach(el=>el.oninput=()=>updateDraft());
 function updateDraft(){readEditorInputs();$('#phonePreview').innerHTML=phone(data.page);editorState('초안을 저장하는 중입니다…');clearTimeout(window.draftTimer);window.draftTimer=setTimeout(async()=>{try{await save();editorState('초안 저장 완료 · 발행본 저장 후 고객 화면에 반영됩니다.')}catch(e){editorState('저장하지 못했습니다. '+e.message)}},600)}
 $('#addCourse').onclick=()=>{if(data.page.courses.length>=40){toast('코스는 40개까지 추가할 수 있습니다.');return}changeCourses(()=>data.page.courses.push({id:uuid(),name:'새 코스',description:'',media:[],coverId:null}))};
 document.querySelectorAll('[data-move-course]').forEach(el=>el.onclick=()=>changeCourses(()=>{const i=Number(el.dataset.moveCourse),j=i+Number(el.dataset.direction);[data.page.courses[i],data.page.courses[j]]=[data.page.courses[j],data.page.courses[i]]}));
 document.querySelectorAll('[data-remove-course]').forEach(el=>el.onclick=()=>{const i=Number(el.dataset.removeCourse);openModal(`<div class="modalhead"><h2>코스를 초안에서 제거할까요?</h2><button class="ghost" id="closeModal">✕</button></div><p>${esc(data.page.courses[i].name)} 코스를 제거합니다. 현재 발행본은 다음 발행 전까지 유지됩니다.</p><button class="primary" id="confirmRemoveCourse">초안에서 제거</button>`);$('#confirmRemoveCourse').onclick=()=>{$('#modal').close();changeCourses(()=>data.page.courses.splice(i,1))}});
 document.querySelectorAll('[data-cover-course]').forEach(el=>el.onclick=()=>changeCourses(()=>{data.page.courses[Number(el.dataset.coverCourse)].coverId=el.dataset.mediaId}));
 document.querySelectorAll('[data-remove-media]').forEach(el=>el.onclick=()=>changeCourses(()=>{const c=data.page.courses[Number(el.dataset.removeMedia)];c.media=c.media.filter(m=>m.id!==el.dataset.mediaId);if(c.coverId===el.dataset.mediaId)c.coverId=c.media[0]?.id||null}));
 document.querySelectorAll('[data-course-upload]').forEach(el=>el.onchange=async()=>{
  const c=data.page.courses.find(c=>c.id===el.dataset.courseUpload),files=[...el.files];if(!files.length)return;
  if(c.media.length+files.length>12){toast('코스별 첨부 파일은 최대 12개입니다.');el.value='';return}
  const mimeByExt={jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp',gif:'image/gif',mp4:'video/mp4',webm:'video/webm'};
  const allowed=Object.values(mimeByExt);for(const f of files){const type=f.type||mimeByExt[f.name.split('.').pop().toLowerCase()],max=type?.startsWith('video/')?25:10;if(!allowed.includes(type)||f.size>max*1024*1024){toast('사진·GIF는 10MB, MP4·WebM은 25MB 이내로 선택해 주세요.');el.value='';return}}
  clearTimeout(window.draftTimer);readEditorInputs();editorBusy(true);let uploaded=0;try{for(const f of files){editorState(`첨부 파일 업로드 중 · ${uploaded+1}/${files.length}`);const type=f.type||mimeByExt[f.name.split('.').pop().toLowerCase()];const res=await fetch('/api/admin/media',{method:'POST',headers:{'Content-Type':type,'X-File-Name':encodeURIComponent(f.name)},body:f});const result=await res.json();if(!res.ok)throw Error(result.error||'파일을 첨부하지 못했습니다.');c.media.push(result);c.coverId=c.coverId||result.id;uploaded++}await save();render();toast('미디어를 첨부했습니다. 발행본 저장 후 고객에게 표시됩니다.')}catch(error){if(uploaded){try{await save()}catch{}}if(current==='page')render();toast(error.message);editorState(error.message)}finally{editorBusy(false)}
 });
 $('#publishPage').onclick=async()=>{clearTimeout(window.draftTimer);readEditorInputs();if(!data.page.title.trim()||!data.page.courses.length||data.page.courses.some(c=>!c.name.trim())){toast('메인 문구와 코스 이름을 입력하고 코스를 한 개 이상 추가해 주세요.');return}editorBusy(true);const previous=data.published;try{data.published=structuredClone(data.page);await save();editorState('발행 완료 · 고객용 페이지에 반영되었습니다.');toast('고객용 페이지에 발행했습니다.')}catch(error){data.published=previous;toast(error.message)}finally{editorBusy(false)}}
}

setInterval(()=>{if(current==='leads'&&!customerView())document.querySelectorAll('[data-local-clock]').forEach(el=>{const l=data.leads.find(l=>l.id===el.dataset.localClock);if(l)el.textContent=localClock(l)})},60000);

let residenceOptions=null;
const cityNames={'Asia/Seoul':'서울','America/Los_Angeles':'로스앤젤레스 · 태평양','America/New_York':'뉴욕 · 동부','America/Chicago':'시카고 · 중부','America/Denver':'덴버 · 산악','America/Phoenix':'피닉스 · 애리조나(나바호 제외)','America/Anchorage':'앵커리지','Pacific/Honolulu':'호놀룰루 · 하와이','America/Toronto':'토론토 · 온타리오/퀘벡 대부분','America/Vancouver':'밴쿠버','America/Edmonton':'에드먼턴','America/Winnipeg':'위니펙','America/Regina':'리자이나','America/Swift_Current':'스위프트커런트','America/St_Johns':'세인트존스','America/Halifax':'핼리팩스','America/Moncton':'멍크턴','America/Blanc-Sablon':'블랑사블롱','America/Atikokan':'아티코칸','Europe/London':'런던','Europe/Dublin':'더블린','Australia/Sydney':'시드니','Australia/Brisbane':'브리즈번','Australia/Perth':'퍼스'};
function residenceForm(){const preferred=['KR','US','CA','AU','NZ','GB','IE','JP','SG'],cs=residenceOptions.countries;const option=c=>`<option value="${esc(c.code)}">${esc(c.name)}</option>`;return `<section class="residence-fields"><h3>거주 지역 · 상담 기준 시간</h3><p class="hint">전화번호·카카오톡 모두 입력해 주세요. 전화 국가번호와 관계없이 실제 거주지를 선택합니다.</p><label for="residenceCountry">거주 국가 *</label><select id="residenceCountry" name="residenceCountry" required><option value="">거주 국가 선택</option><optgroup label="주요 국가">${preferred.map(code=>cs.find(c=>c.code===code)).filter(Boolean).map(option).join('')}</optgroup><optgroup label="기타 국가 및 지역">${cs.filter(c=>!preferred.includes(c.code)).map(option).join('')}</optgroup></select><div id="residenceRegionSelectField" hidden><label for="residenceRegionCode">거주 주 / 도 *</label><select id="residenceRegionCode" name="residenceRegionCode" disabled><option value="">주 / 도 선택</option></select></div><div id="residenceRegionTextField"><label for="residenceRegion">거주 지역 *</label><input id="residenceRegion" name="residenceRegion" maxlength="120" required placeholder="예: 서울특별시 / 뉴사우스웨일스"></div><label for="residenceTimezone">거주 지역 시간대 *</label><select id="residenceTimezone" name="residenceTimezone" required disabled><option value="">거주 국가를 먼저 선택해 주세요.</option></select><p class="hint">같은 주·도 안에서도 시간대가 다를 수 있습니다. 거주지와 같은 시계를 사용하는 대표 도시를 선택해 주세요. 단순히 가까운 도시를 선택하지 마세요.</p><div id="residenceClock" class="residence-clock" aria-live="polite">시간대를 선택하면 해당 지역의 현재 시각을 보여드립니다.</div><button type="button" class="ghost" id="useDeviceZone">내 기기 시간대 확인 · 적용</button><p class="hint" id="deviceZoneHint"></p><label class="checkrow"><input id="residenceConfirmed" name="residenceConfirmed" type="checkbox" required><span>선택한 지역·시간대가 실제 거주지와 일치하는지 확인했습니다. *</span></label></section>`}
const regionZoneSuggestions={US:{CA:['America/Los_Angeles'],NY:['America/New_York'],WA:['America/Los_Angeles'],IL:['America/Chicago'],CO:['America/Denver'],MA:['America/New_York'],NJ:['America/New_York'],GA:['America/New_York'],NC:['America/New_York'],SC:['America/New_York'],PA:['America/New_York'],VA:['America/New_York'],MD:['America/New_York'],DC:['America/New_York'],CT:['America/New_York'],DE:['America/New_York'],ME:['America/New_York'],NH:['America/New_York'],RI:['America/New_York'],VT:['America/New_York'],OH:['America/New_York'],WI:['America/Chicago'],MN:['America/Chicago'],IA:['America/Chicago'],MO:['America/Chicago'],AR:['America/Chicago'],AL:['America/Chicago'],MS:['America/Chicago'],LA:['America/Chicago'],OK:['America/Chicago'],UT:['America/Denver'],NM:['America/Denver'],MT:['America/Denver'],HI:['Pacific/Honolulu'],TX:['America/Chicago','America/Denver'],FL:['America/New_York','America/Chicago'],AZ:['America/Phoenix','America/Denver'],ID:['America/Boise','America/Los_Angeles'],OR:['America/Los_Angeles','America/Boise'],NV:['America/Los_Angeles','America/Denver']},CA:{AB:['America/Edmonton'],MB:['America/Winnipeg'],NB:['America/Moncton'],NL:['America/St_Johns','America/Goose_Bay'],NS:['America/Halifax','America/Glace_Bay'],PE:['America/Halifax'],QC:['America/Toronto','America/Blanc-Sablon'],ON:['America/Toronto','America/Atikokan','America/Winnipeg'],SK:['America/Regina','America/Swift_Current','America/Edmonton'],BC:['America/Vancouver','America/Creston','America/Dawson_Creek','America/Fort_Nelson','America/Edmonton'],NT:['America/Edmonton','America/Inuvik'],NU:['America/Iqaluit','America/Resolute','America/Rankin_Inlet','America/Cambridge_Bay','America/Atikokan'],YT:['America/Whitehorse','America/Dawson']}};
function setupResidenceForm(){const country=$('#residenceCountry'),region=$('#residenceRegionCode'),zone=$('#residenceTimezone');
 const clearConfirmation=()=>{$('#residenceConfirmed').checked=false};
 const updateClock=()=>{const value=zone.value;clearConfirmation();if(!value){$('#residenceClock').textContent='시간대를 선택하면 해당 지역의 현재 시각을 보여드립니다.';return}try{const current=new Date(),local=new Intl.DateTimeFormat('ko-KR',{timeZone:value,dateStyle:'full',timeStyle:'short'}).format(current),offset=new Intl.DateTimeFormat('en-US',{timeZone:value,timeZoneName:'shortOffset'}).formatToParts(current).find(p=>p.type==='timeZoneName')?.value||'';$('#residenceClock').textContent=`선택한 지역의 현재 시각: ${local} (${offset}) · ${value}`}catch{$('#residenceClock').textContent='이 시간대를 표시할 수 없습니다. 다른 항목을 확인해 주세요.'}};
 country.onchange=()=>{clearConfirmation();const c=residenceOptions.countries.find(c=>c.code===country.value),rs=residenceOptions.regions[country.value]||[];$('#residenceRegionSelectField').hidden=!rs.length;region.disabled=!rs.length;region.required=!!rs.length;$('#residenceRegionTextField').hidden=!!rs.length;$('#residenceRegion').disabled=!!rs.length;$('#residenceRegion').required=!rs.length;$('#residenceRegion').value='';region.innerHTML='<option value="">주 / 도 선택</option>'+rs.map(([code,name])=>`<option value="${esc(code)}">${esc(name)}</option>`).join('');zone.disabled=!c;zone.innerHTML='<option value="">'+(c?'거주 지역 시간대 선택':'거주 국가를 먼저 선택해 주세요.')+'</option>'+(c?c.zones.map(z=>`<option value="${esc(z.id)}">${esc(cityNames[z.id]||z.id.split('/').at(-1).replaceAll('_',' '))} — ${esc(z.id)}${z.description?' · '+esc(z.description):''}</option>`).join(''):'');if(c?.zones.length===1)zone.value=c.zones[0].id;$('#deviceZoneHint').textContent='';updateClock()};
 region.onchange=()=>{const c=residenceOptions.countries.find(c=>c.code===country.value),suggestions=regionZoneSuggestions[country.value]?.[region.value]||[],recommended=(c?.zones||[]).filter(z=>suggestions.includes(z.id)),other=(c?.zones||[]).filter(z=>!suggestions.includes(z.id));const renderOption=z=>`<option value="${esc(z.id)}">${esc(cityNames[z.id]||z.id.split('/').at(-1).replaceAll('_',' '))} — ${esc(z.id)}${z.description?' · '+esc(z.description):''}</option>`;zone.innerHTML='<option value="">거주 지역 시간대 선택</option>'+(recommended.length?'<optgroup label="선택한 주·도에서 사용하는 시간대">'+recommended.map(renderOption).join('')+'</optgroup>':'')+'<optgroup label="같은 국가의 다른 세부 지역 시간대">'+other.map(renderOption).join('')+'</optgroup>';if(recommended.length===1)zone.value=recommended[0].id;else zone.value='';updateClock()};zone.onchange=updateClock;$('#residenceRegion').oninput=clearConfirmation;
 $('#useDeviceZone').onclick=()=>{let detected='';try{detected=Intl.DateTimeFormat().resolvedOptions().timeZone}catch{}if(!detected){$('#deviceZoneHint').textContent='기기 시간대를 확인할 수 없습니다. 직접 선택해 주세요.';return}const c=residenceOptions.countries.find(c=>c.code===country.value);const canonical=id=>{try{return new Intl.DateTimeFormat('en',{timeZone:id}).resolvedOptions().timeZone}catch{return ''}};const match=c?.zones.find(z=>canonical(z.id)===canonical(detected));if(match){zone.value=match.id;updateClock();$('#deviceZoneHint').textContent=`기기 시간대 ${detected}를 적용했습니다. 실제 거주 시간대와 일치하는지 확인해 주세요.`}else $('#deviceZoneHint').textContent=`기기 시간대: ${detected}. 선택한 국가의 시간대와 일치하지 않습니다. 거주 국가와 시간대를 직접 확인해 주세요.`};
}
function readResidenceForm(){const code=$('#residenceCountry').value,c=residenceOptions.countries.find(c=>c.code===code),rs=residenceOptions.regions[code]||[],regionCode=rs.length?$('#residenceRegionCode').value:null;return {countryCode:code,regionCode,region:rs.length?(rs.find(r=>r[0]===regionCode)?.[1]||''):$('#residenceRegion').value.trim(),timezone:$('#residenceTimezone').value,confirmed:$('#residenceConfirmed').checked}}

async function checkMondayConnection(targetId,submitSelector){const target=$('#'+targetId);target.textContent='Distance와 Revenue 연결을 확인하고 있습니다…';const submit=submitSelector?$(submitSelector):null;if(submit)submit.disabled=true;try{const r=await api('admin/monday/check','POST',{});const provider=r.provider;target.innerHTML=`<div class="banner">${esc(r.summary||'연결 응답을 확인해 주세요.')}${(r.checks||[]).map(c=>`<p class="hint"><strong>${esc(c.name)}</strong> · ${c.ready?'연결 확인':'연결 확인 필요'}<br>${esc(c.summary)}</p>`).join('')}${r.signInUrl?`<p><a href="${esc(r.signInUrl)}" target="_top">직원 계정으로 연결</a></p>`:''}${provider?.retryAfterMs?`<p class="hint">다시 확인하기까지 ${Math.ceil(provider.retryAfterMs/1000)}초 대기해 주세요.</p>`:''}</div>`;if(submit)submit.disabled=!r.ready}catch(e){target.textContent=e.message;if(submit)submit.disabled=true}}

function funnelView(){return heading('학생 현황 · 집계 기준','인포허브와 레비뉴 등 먼데이 원본을 기준으로 Growth BI에서 조회합니다.')+studentMetricsView();}

